  const cases=[[s=>{s.reservations[0].startAt=123},/startAt는 실제로 존재하는 시각/],[s=>{s.reservations[0].depositAmount='10000'},/depositAmount는 유한한 숫자/],[s=>{s.services[0].active='yes'},/active는 true 또는 false/],[s=>{s.services={}},/서비스 목록이 배열이 아닙니다/],[s=>{s.customers[0].visitCount='x'},/visitCount는 유한한 숫자/],[s=>{s.reservations[0]='text'},/객체가 아닙니다/],[s=>{s.staff[0].serviceIds='SVC-CUT'},/serviceIds는 배열/],[s=>{s.customers[0].name=42},/name는 문자열/],[s=>{s.reservations[0].depositAmount=-1},/depositAmount는 0 이상/],[s=>{s.services[0].durationMin=0},/durationMin는 1 이상/],[s=>{s.revision=1.5},/revision는 정수/],[s=>{s.policy.requireDeposit='true'},/requireDeposit는 true 또는 false/],[s=>{s.waitlist[0].note=null},/note는 문자열/],[s=>{s.reservations[0].note='x'.repeat(5001)},/note가 너무 깁니다/]];
