test('backup: dates that do not exist are rejected, real ones are accepted',()=>{
  for(const bad of ['2026-02-30T10:00:00.000Z','2026-13-01T00:00:00.000Z','not-a-date','2026-09-29 10:00:00','2026-09-29T25:00:00.000Z','2026-09-29T10:61:00.000Z','2026-09-29T10:00:00','2026-02-29T00:00:00.000Z',20260929,null,'']){const r=inspect(mutated(s=>{s.reservations[0].startAt=bad}));assert.equal(r.ok,false,String(bad));assert.match(r.errors.join('\n'),/startAt는 실제로 존재하는 시각/)}
  for(const good of ['2026-09-29T10:00:00.000Z','2026-09-29T10:00:00Z','2026-09-29T19:00:00+09:00','2028-02-29T00:00:00.000Z']){assert.equal(inspect(mutated(s=>{s.reservations[0].startAt=good;s.reservations[0].endAt='2029-01-01T00:00:00.000Z'})).ok,true,good)}
  assert.match(errorText(mutated(s=>{s.simulatedNow='2026-99-99T00:00:00.000Z'})),/simulatedNow/);assert.match(errorText(mutated(s=>{s.audit[0].at='x'})),/감사 이력 1번째.*at는/);assert.match(errorText(mutated(s=>{s.reservations[4].cancelledAt='nope'})),/cancelledAt/);assert.match(errorText(mutated(s=>{s.reservations[0].createdAt=5})),/createdAt/);
  assert.match(errorText(mutated(s=>{s.reservations[0].endAt=s.reservations[0].startAt})),/endAt은 startAt보다 뒤/);assert.match(errorText(mutated(s=>{s.waitlist[0].windowEnd=s.waitlist[0].windowStart})),/windowEnd는 windowStart보다 뒤/);const o=withOffer();const w=o.waitlist.find(x=>x.id==='WAIT-001');w.offer.slotEnd=w.offer.slotStart;assert.match(errorText(o),/slotEnd는 slotStart보다 뒤/)});
test('backup: array size limits are enforced (and exactly the limit is accepted)',()=>{
  const fill=(key,n,make)=>{const s=seed();s[key]=Array.from({length:n},(_,i)=>make(s,i));return s};
  const cases=[['reservations',3001,(s,i)=>({...s.reservations[0],id:'R'+i}),/예약가 너무 많습니다: 3001개 \(최대 3000개\)/],['waitlist',3001,(s,i)=>({...s.waitlist[0],id:'W'+i}),/대기자가 너무 많습니다: 3001개 \(최대 3000개\)/],['audit',10001,(s,i)=>({...s.audit[0],id:'A'+i}),/감사 이력가 너무 많습니다: 10001개 \(최대 10000개\)/],['customers',5001,(s,i)=>({...s.customers[0],id:'C'+i}),/고객가 너무 많습니다: 5001개 \(최대 5000개\)/],['services',101,(s,i)=>({...s.services[0],id:'S'+i}),/서비스가 너무 많습니다: 101개 \(최대 100개\)/],['staff',101,(s,i)=>({...s.staff[0],id:'T'+i}),/담당자가 너무 많습니다: 101개 \(최대 100개\)/]];
  for(const [key,n,make,re] of cases){const r=inspect(fill(key,n,make));assert.equal(r.ok,false,key);assert.match(r.errors.join('\n'),re);assert.equal(r.totalErrors,1,`${key}: only the size error, no follow-up noise: ${r.errors.join(' | ')}`)}
  assert.equal(inspect(fill('reservations',3000,(s,i)=>({...s.reservations[0],id:'R'+i}))).ok,true);assert.equal(inspect(fill('audit',10000,(s,i)=>({...s.audit[0],id:'A'+i}))).ok,true);assert.equal(bk.BACKUP_LIMITS.reservations,3000)});
