test('restore safety: a rejected backup never touches the stored data, even when it is passed straight to the repository',()=>{
  const good=seed();const raw=JSON.stringify(good);const st=countingStore(raw);const repo=new LocalRepository(st);repo.load();
  const bads=[mutated(s=>{s.reservations[0].status='banana'}),mutated(s=>{s.reservations[0].customerId='CUS-999'}),mutated(s=>{s.customers.push({...s.customers[0]})}),mutated(s=>{s.reservations[0].startAt='2026-02-30T00:00:00.000Z'}),mutated(s=>{delete s.policy}),{schemaVersion:1}];
  for(const bad of bads){const r=inspect(bad);assert.equal(r.ok,false);assert.equal(st.c.set,0,'inspecting must not write');assert.throws(()=>repo.replace(bad),/복원할 자료가 올바르지 않아 복원하지 않았습니다. 현재 자료는 바뀌지 않았습니다/);assert.equal(repo.raw(),raw)}
  assert.equal(st.c.set,0);assert.equal(st.c.remove,0);assert.deepEqual(new LocalRepository(st).load().state,good);repo.save(eng.payDeposit(good,'RSV-1004'));assert.equal(st.c.set,1)});
test('restore safety: a rejected backup keeps recovery mode and the unreadable original',()=>{const st=memStore('{broken');const repo=new LocalRepository(st);assert.equal(repo.load().mode,'recovery');assert.throws(()=>repo.replace(mutated(s=>{s.reservations[0].status='banana'})),/복원하지 않았습니다/);assert.equal(st.getItem(STORAGE_KEY),'{broken');assert.throws(()=>repo.save(seed()),/복구 모드/);repo.replace(seed());assert.equal(new LocalRepository(st).load().mode,'persistent')});
test('restore safety: a valid backup that does not fit in storage leaves the current data untouched',()=>{
  const cur=JSON.stringify(seed());const st=quotaStore(cur.length+500,cur);const repo=new LocalRepository(st);repo.load();const big=bigValid();assert.equal(inspect(big).ok,true);
  assert.throws(()=>repo.replace(big),/저장 공간이 부족하거나 권한이 없어 복원하지 못했습니다. 기존 자료는 유지됩니다/);assert.equal(st.getItem(STORAGE_KEY),cur);assert.deepEqual(new LocalRepository(st).load().state,seed());repo.save(eng.payDeposit(seed(),'RSV-1004'));assert.ok(st.getItem(STORAGE_KEY).length<=cur.length+500)});
test('restore safety: a failed write that clobbered the stored value is rolled back',()=>{const cur=JSON.stringify(seed());let v=cur,calls=0;const st={getItem:()=>v,setItem:(k,x)=>{calls++;if(calls===1){v=x.slice(0,15);throw Error('quota')}v=x},removeItem:()=>{v=null}};const repo=new LocalRepository(st);repo.load();assert.throws(()=>repo.replace(bigValid()),/복원하지 못했습니다/);assert.equal(v,cur)});
test('restore safety: the seed used by "reset" is always valid',()=>{assert.equal(inspect(seed()).ok,true);assert.equal(bk.validateState(makeSeedForReset()).ok,true)});
function makeSeedForReset(){return require('../.test-build/src/data/seed.js').makeSeed()}

test('restore policy: a backup where only policy numbers are unusable is repaired like P0-1, everything else is kept',()=>{
  const s=seed();s.policy={...s.policy,slotMinutes:0,offerHoldMin:-1,cancellationHours:NaN,openingHour:20,closingHour:19};const r=inspect(JSON.stringify(s));assert.equal(r.ok,true,r.errors.join('\n'));assert.equal(r.notes.length,1);assert.match(r.notes[0],/기본 슬롯\(분\) 0 → 30/);assert.match(r.notes[0],/빈자리 제안 홀드\(분\) -1 → 20/);assert.match(r.notes[0],/취소 기준 시간 없음 → 24/);assert.match(r.notes[0],/영업시간 20~19 → 9~19/);
  assert.deepEqual(polMod.policyProblems(r.state.policy),[]);const base=seed();assert.deepEqual(r.state.reservations,base.reservations);assert.deepEqual(r.state.customers,base.customers);assert.deepEqual(r.state.waitlist,base.waitlist);assert.deepEqual(r.state.services,base.services);assert.equal(r.state.audit.length,base.audit.length+1);assert.equal(r.state.audit[0].type,'policy');assert.equal(r.state.policy.businessName,base.policy.businessName);
  const st=memStore(JSON.stringify(seed()));const repo=new LocalRepository(st);repo.load();repo.replace(r.state);assert.deepEqual(polMod.policyProblems(JSON.parse(st.getItem(STORAGE_KEY)).policy),[]);assert.equal(new LocalRepository(st).load().notice,'')});
test('restore policy: a repaired policy does not hide other problems, and non-numeric policy fields are still errors',()=>{const both=seed();both.policy.slotMinutes=0;both.reservations[0].status='banana';const r=inspect(both);assert.equal(r.ok,false);assert.deepEqual(r.notes,[]);assert.match(r.errors.join('\n'),/status 값 "banana"/);assert.match(errorText(mutated(s=>{s.policy.requireDeposit='yes'})),/requireDeposit/);assert.equal(inspect(mutated(s=>{s.policy.slotMinutes=0})).ok,true)});
test('restore policy: repairing keeps the audit log within its limit',()=>{const s=seed();s.policy.slotMinutes=0;s.audit=Array.from({length:10000},(_,i)=>({...s.audit[0],id:'A'+i}));const r=inspect(s);assert.equal(r.ok,true);assert.equal(r.state.audit.length,10000);assert.equal(r.state.audit[0].type,'policy')});

test('restore confirmation: the final restore needs a valid backup AND the exact word',()=>{
  const ok=inspect(seed());assert.equal(bk.RESTORE_CONFIRM_TEXT,'복원');
  for(const typed of ['','복','복원 ',' 복원','복원복원','restore','RESTORE','복 원','복원\n','확인'])assert.equal(bk.canConfirmRestore(ok,typed),false,JSON.stringify(typed));
  assert.equal(bk.canConfirmRestore(ok,'복원'),true);
  const failed=inspect(mutated(s=>{s.reservations[0].status='banana'}));assert.equal(bk.canConfirmRestore(failed,'복원'),false);assert.equal(bk.canConfirmRestore(null,'복원'),false);assert.equal(bk.canConfirmRestore(undefined,'복원'),false);assert.equal(bk.canConfirmRestore({ok:true,errors:[],totalErrors:0,notes:[]},'복원'),false);
  const repaired=inspect(mutated(s=>{s.policy.slotMinutes=0}));assert.equal(bk.canConfirmRestore(repaired,''),false);assert.equal(bk.canConfirmRestore(repaired,'복원'),true)});

test('restore preview: summarizes what changes between the current data and the backup',()=>{
  const current=seed();const next=seed();next.reservations.push({...next.reservations[0],id:'RSV-NEW',status:'cancelled'});next.reservations=next.reservations.filter(r=>r.id!=='RSV-1008');next.customers.push({id:'CUS-NEW',name:'새 고객',phone:'',email:'',notes:'',visitCount:0,noShowCount:0});next.waitlist=next.waitlist.filter(w=>w.id!=='WAIT-003');next.policy.slotMinutes=15;next.policy.requireDeposit=false;next.policy.businessName='다른 점포';next.simulatedNow=isoAt(30,9);
  const sum=bk.describeRestore(current,next);const row=l=>sum.rows.find(r=>r.label===l);
  assert.deepEqual([row('고객').current,row('고객').next],[8,9]);assert.deepEqual([row('예약').current,row('예약').next],[8,8]);assert.deepEqual([row('대기자').current,row('대기자').next],[3,2]);
  assert.deepEqual(sum.onlyInCurrent.map(r=>[r.label,r.current]),[['고객',0],['예약',1],['대기자',1]]);assert.deepEqual(sum.onlyInBackup.map(r=>[r.label,r.next]),[['고객',1],['예약',1],['대기자',0]]);
  const cancelled=sum.reservationStatus.find(r=>r.label==='예약 취소');assert.deepEqual([cancelled.current,cancelled.next],[1,2]);
  assert.ok(sum.policyChanges.some(x=>/기본 슬롯\(분\) 30 → 15/.test(x)));assert.ok(sum.policyChanges.some(x=>/예약금 사용 켬 → 끔/.test(x)));assert.ok(sum.policyChanges.some(x=>/사업장 이름/.test(x)));assert.notEqual(sum.clock.current,sum.clock.next);
  const same=bk.describeRestore(seed(),seed());assert.deepEqual(same.policyChanges,[]);assert.deepEqual(same.onlyInCurrent.map(r=>r.current),[0,0,0]);assert.deepEqual(same.onlyInBackup.map(r=>r.next),[0,0,0])});
test('restore preview: a repaired policy is reported with the before/after values and shows up in the summary',()=>{const s=seed();s.policy.slotMinutes=0;const r=inspect(s);const sum=bk.describeRestore(seed(),r.state);assert.deepEqual(sum.policyChanges,[]);assert.match(r.notes[0],/기본 슬롯\(분\) 0 → 30/)});

// ---- P0-3 deposit integrity: the deposit requirement is fixed per reservation, deposits are never paid on closed reservations,
// ---- a no-show settles a paid deposit, a recovered reservation is not auto-paid, arrived cannot be cancelled and only confirmed can be a no-show.
const dRes=(s,id)=>s.reservations.find(r=>r.id===id);
const dPair=r=>[r.status,r.depositStatus];
const dBooking=s=>{const n=eng.createReservation(s,{customerId:'CUS-006',serviceId:'SVC-CUT',staffId:'ST-B',startAt:isoAt(30,17)});return {s:n,id:n.reservations[0].id}};

test('deposit: paying is rejected on a cancelled reservation',()=>{let s=seed();s=eng.cancelReservation(s,'RSV-1004','x');assert.deepEqual(dPair(dRes(s,'RSV-1004')),['cancelled','unpaid']);assert.throws(()=>eng.payDeposit(s,'RSV-1004'),/결제할 수 없습니다/)});
test('deposit: paying is rejected on a no_show reservation',()=>{let s=seed();s=eng.changeClock(s,isoAt(29,14));dRes(s,'RSV-1004').status='confirmed';s=eng.markNoShow(s,'RSV-1004');assert.deepEqual(dPair(dRes(s,'RSV-1004')),['no_show','unpaid']);assert.throws(()=>eng.payDeposit(s,'RSV-1004'),/결제할 수 없습니다/)});
test('deposit: paying is rejected on a completed reservation (legacy state that still owes a deposit)',()=>{const s=seed();dRes(s,'RSV-1001').depositStatus='unpaid';assert.equal(dRes(s,'RSV-1001').status,'completed');assert.throws(()=>eng.payDeposit(s,'RSV-1001'),/결제할 수 없습니다/)});
test('deposit: paying still works while requested, confirmed or arrived',()=>{let s=seed();s=eng.payDeposit(s,'RSV-1004');assert.deepEqual(dPair(dRes(s,'RSV-1004')),['requested','paid']);for(const status of ['confirmed','arrived']){const t=seed();const r=dRes(t,'RSV-1003');r.status=status;r.depositStatus='unpaid';assert.equal(dRes(eng.payDeposit(t,'RSV-1003'),'RSV-1003').depositStatus,'paid',status)}});
test('deposit: canPayDeposit is true only for a live reservation that still owes a deposit',()=>{const s=seed();assert.equal(rules.canPayDeposit(dRes(s,'RSV-1004')),true);for(const id of ['RSV-1001','RSV-1002','RSV-1003','RSV-1005'])assert.equal(rules.canPayDeposit(dRes(s,id)),false,id);const t=seed();for(const status of ['cancelled','completed','no_show']){dRes(t,'RSV-1004').status=status;assert.equal(rules.canPayDeposit(dRes(t,'RSV-1004')),false,status)}});

test('deposit: a no-show with forfeit OFF refunds the paid deposit and the audit entry says so',()=>{let s=seed();s=eng.updatePolicy(s,{noShowForfeit:false});s=eng.markNoShow(s,'RSV-1002');assert.deepEqual(dPair(dRes(s,'RSV-1002')),['no_show','refunded']);assert.equal(s.audit[0].type,'noshow');assert.match(s.audit[0].message,/모의 환불/)});
test('deposit: a no-show with forfeit ON forfeits the paid deposit and the audit entry says so',()=>{let s=seed();s=eng.markNoShow(s,'RSV-1002');assert.deepEqual(dPair(dRes(s,'RSV-1002')),['no_show','forfeited']);assert.equal(s.audit[0].type,'noshow');assert.match(s.audit[0].message,/모의 차감/)});

test('deposit: accepting an offer makes a requested + unpaid reservation when a deposit is required; it is confirmed only after a mock payment',()=>{
  let s=seed();s=eng.offerCancelledSlot(s,'WAIT-001','RSV-1005');const deposits=()=>s.audit.filter(a=>a.type==='deposit').length;const before=deposits();
  s=eng.acceptOffer(s,'WAIT-001');const r=s.reservations.find(x=>x.source==='waitlist');
  assert.deepEqual([r.status,r.depositStatus,r.depositAmount],['requested','unpaid',10000]);assert.equal(s.waitlist.find(w=>w.id==='WAIT-001').status,'booked');assert.equal(s.waitlist.find(w=>w.id==='WAIT-001').offer.status,'accepted');
  assert.equal(r.recoveredFromReservationId,'RSV-1005');assert.equal(r.waitlistId,'WAIT-001');assert.equal(deposits(),before,'no deposit event without a payment action');
  assert.throws(()=>eng.confirmReservation(s,r.id),/예약금 모의 결제/);
  s=eng.payDeposit(s,r.id);assert.equal(deposits(),before+1);s=eng.confirmReservation(s,r.id);assert.deepEqual(dPair(dRes(s,r.id)),['confirmed','paid'])});
test('deposit: the unpaid recovered reservation still occupies the slot',()=>{let s=seed();s=eng.offerCancelledSlot(s,'WAIT-001','RSV-1005');s=eng.acceptOffer(s,'WAIT-001');const r=s.reservations.find(x=>x.source==='waitlist');assert.equal(rules.bookingCheck(s,{customerId:'CUS-002',serviceId:'SVC-CUT',staffId:r.staffId,startAt:r.startAt}).ok,false)});
test('deposit: accepting an offer that needs no deposit confirms it at once (policy OFF, or service deposit 0)',()=>{
  let s=seed();s=eng.updatePolicy(s,{requireDeposit:false});s=eng.offerCancelledSlot(s,'WAIT-001','RSV-1005');s=eng.acceptOffer(s,'WAIT-001');let r=s.reservations.find(x=>x.source==='waitlist');assert.deepEqual([r.status,r.depositStatus,r.depositAmount],['confirmed','not_required',0]);
  let t=seed();t.services.find(x=>x.id==='SVC-CUT').deposit=0;t=eng.offerCancelledSlot(t,'WAIT-001','RSV-1005');t=eng.acceptOffer(t,'WAIT-001');r=t.reservations.find(x=>x.source==='waitlist');assert.deepEqual([r.status,r.depositStatus,r.depositAmount],['confirmed','not_required',0])});

test('deposit: an arrived reservation cannot be cancelled (engine and decision helper)',()=>{let s=seed();s=eng.markArrived(s,'RSV-1006');assert.throws(()=>eng.cancelReservation(s,'RSV-1006','x'),/도착/);assert.equal(rules.cancellationDecision(s,dRes(s,'RSV-1006')).allowed,false);assert.deepEqual(dPair(dRes(s,'RSV-1006')),['arrived','paid'])});
test('deposit: requested and confirmed reservations are still cancellable with the same refund / forfeit / unpaid outcomes',()=>{let s=seed();s=eng.cancelReservation(s,'RSV-1008','x');assert.deepEqual(dPair(dRes(s,'RSV-1008')),['cancelled','refunded']);let t=seed();t.policy.cancellationHours=48;t=eng.cancelReservation(t,'RSV-1006','x');assert.deepEqual(dPair(dRes(t,'RSV-1006')),['cancelled','forfeited']);assert.deepEqual(dPair(dRes(eng.cancelReservation(seed(),'RSV-1004','x'),'RSV-1004')),['cancelled','unpaid'])});

test('deposit: a reservation made while a deposit was required still needs it after the global policy is switched OFF',()=>{let {s,id}=dBooking(seed());assert.deepEqual(dPair(dRes(s,id)),['requested','unpaid']);s=eng.updatePolicy(s,{requireDeposit:false});assert.throws(()=>eng.confirmReservation(s,id),/예약금 모의 결제/);s=eng.payDeposit(s,id);s=eng.confirmReservation(s,id);assert.deepEqual(dPair(dRes(s,id)),['confirmed','paid'])});
test('deposit: the seeded unpaid reservation keeps its requirement after the policy is switched OFF',()=>{const s=eng.updatePolicy(seed(),{requireDeposit:false});assert.throws(()=>eng.confirmReservation(s,'RSV-1004'),/예약금 모의 결제/)});
test('deposit: a reservation made while NO deposit was required stays deposit-free after the policy is switched ON',()=>{let s=eng.updatePolicy(seed(),{requireDeposit:false});let {s:t,id}=dBooking(s);assert.deepEqual([...dPair(dRes(t,id)),dRes(t,id).depositAmount],['requested','not_required',0]);t=eng.updatePolicy(t,{requireDeposit:true});t=eng.confirmReservation(t,id);assert.deepEqual(dPair(dRes(t,id)),['confirmed','not_required'])});
test('deposit: a CSV-imported reservation keeps the requirement it was created with',()=>{let s=seed();const p=csv.previewReservationsCsv(`id,customerId,serviceId,staffId,startAt,note\nR-9,CUS-006,SVC-CARE,ST-A,${isoAt(31,10)},x\n`,s);assert.equal(p.issues.length,0);s=csv.applyImportedReservations(s,p.rows);assert.deepEqual(dPair(dRes(s,'R-9')),['requested','unpaid']);s=eng.updatePolicy(s,{requireDeposit:false});assert.throws(()=>eng.confirmReservation(s,'R-9'),/예약금 모의 결제/)});
test('deposit: switching the global deposit policy never rewrites existing reservations',()=>{const s=seed();const snap=x=>JSON.stringify(x.reservations.map(r=>[r.id,r.status,r.depositStatus,r.depositAmount]));assert.equal(snap(eng.updatePolicy(s,{requireDeposit:false})),snap(s));assert.equal(snap(eng.updatePolicy(eng.updatePolicy(s,{requireDeposit:false}),{requireDeposit:true})),snap(s))});

test('no-show: a requested reservation cannot be a no-show, even after the grace period and even when the deposit is paid',()=>{let s=seed();s=eng.changeClock(s,isoAt(29,14));assert.equal(dRes(s,'RSV-1004').status,'requested');assert.throws(()=>eng.markNoShow(s,'RSV-1004'),/확정된 예약만/);const paid=eng.payDeposit(s,'RSV-1004');assert.throws(()=>eng.markNoShow(paid,'RSV-1004'),/확정된 예약만/);assert.equal(rules.canMarkNoShow(s,dRes(s,'RSV-1004')),false)});
test('no-show: an arrived reservation cannot become a no-show',()=>{let s=seed();s=eng.markArrived(s,'RSV-1006');s=eng.changeClock(s,isoAt(29,17));assert.throws(()=>eng.markNoShow(s,'RSV-1006'),/확정된 예약만/);assert.equal(rules.canMarkNoShow(s,dRes(s,'RSV-1006')),false)});
test('no-show: only a confirmed reservation after the grace period can be a no-show',()=>{let s=seed();assert.equal(rules.canMarkNoShow(s,dRes(s,'RSV-1002')),true);s=eng.markNoShow(s,'RSV-1002');assert.equal(dRes(s,'RSV-1002').status,'no_show');for(const id of ['RSV-1001','RSV-1005'])assert.equal(rules.canMarkNoShow(s,dRes(s,id)),false,id)});

function lcg(n){let x=n>>>0;return()=>((x=(Math.imul(x,1664525)+1013904223)>>>0)/2**32)}
function depositViolations(s){const bad=[];for(const r of s.reservations){const t=r.status,d=r.depositStatus;if(['cancelled','no_show'].includes(t)&&d==='paid')bad.push(`${t}+paid`);if(['refunded','forfeited'].includes(d)&&!['cancelled','no_show'].includes(t))bad.push(`${t}+${d}`);if(['confirmed','arrived','completed'].includes(t)&&d==='unpaid')bad.push(`${t}+unpaid`);if(d==='not_required'&&r.depositAmount!==0)bad.push('not_required with an amount')}return bad}
test('deposit invariants: random command sequences never produce a contradictory reservation/deposit state, and every state is a valid backup',()=>{
  const found=new Set();let steps=0;
  for(let sq=1;sq<=250;sq++){const rand=lcg(sq*7919);const pick=a=>a[Math.floor(rand()*a.length)];let s=seed();
    for(let i=0;i<40;i++){const r=s.reservations.length?pick(s.reservations):null,w=s.waitlist.length?pick(s.waitlist):null,op=Math.floor(rand()*13);const prior=r&&r.status;
      const ops=[()=>eng.createReservation(s,{customerId:pick(s.customers).id,serviceId:pick(s.services).id,staffId:pick(s.staff).id,startAt:isoAt(29+Math.floor(rand()*3),9+Math.floor(rand()*9),rand()<0.5?0:30)}),()=>eng.payDeposit(s,r.id),()=>eng.confirmReservation(s,r.id),()=>eng.markArrived(s,r.id),()=>eng.completeReservation(s,r.id),()=>eng.cancelReservation(s,r.id,'x'),()=>eng.markNoShow(s,r.id),()=>eng.offerCancelledSlot(s,w.id,pick(s.reservations.filter(x=>x.status==='cancelled')).id),()=>eng.acceptOffer(s,w.id),()=>eng.declineOffer(s,w.id),()=>eng.changeClock(s,new Date(new Date(s.simulatedNow).getTime()+Math.floor(rand()*8)*3600000).toISOString()),()=>eng.updatePolicy(s,{requireDeposit:rand()<0.5,noShowForfeit:rand()<0.5,lateCancelForfeit:rand()<0.5}),()=>eng.updatePolicy(s,{noShowForfeit:rand()<0.5})];
      let nx;try{nx=ops[op]()}catch{continue}
      s=nx;steps++;if(op===1&&!['requested','confirmed','arrived'].includes(prior))found.add(`paid a deposit on ${prior}`);if(op===5&&!['requested','confirmed'].includes(prior))found.add(`cancelled from ${prior}`);if(op===6&&prior!=='confirmed')found.add(`no-show from ${prior}`);
      for(const b of depositViolations(s))found.add(b);const v=bk.validateState(s);if(!v.ok)found.add('INVALID BACKUP: '+v.errors[0])}}
  assert.ok(steps>3000,`enough successful steps (${steps})`);assert.deepEqual([...found],[],'contradictory results: '+[...found].join(' | '))});
